def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for i, operation in enumerate(ops):
        tokens = operation.split()
        verb = tokens[0] if tokens else ""
        success = False
        action = None

        if verb == "undo" and len(tokens) == 1:
            if history:
                action = history.pop()
                kind = action[0]

                if kind == "open":
                    _, account = action
                    del balances[account]
                elif kind == "deposit":
                    _, account, amount = action
                    balances[account] -= amount
                elif kind == "withdraw":
                    _, account, amount = action
                    balances[account] += amount
                elif kind == "transfer":
                    _, source, target, amount = action
                    balances[source] += amount
                    balances[target] -= amount
                elif kind == "freeze":
                    _, account, was_frozen = action
                    if was_frozen:
                        frozen.add(account)
                    else:
                        frozen.discard(account)
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(tokens) == 3:
            _, account, raw_amount = tokens
            if raw_amount.isascii() and raw_amount.isdigit():
                amount = int(raw_amount)

                if verb == "open":
                    if account not in balances:
                        balances[account] = amount
                        action = ("open", account)
                        success = True
                elif verb == "deposit":
                    if amount > 0 and account in balances:
                        balances[account] += amount
                        action = ("deposit", account, amount)
                        success = True
                elif amount > 0 and account in balances and account not in frozen:
                    if balances[account] >= amount:
                        balances[account] -= amount
                        action = ("withdraw", account, amount)
                        success = True

        elif verb == "transfer" and len(tokens) == 4:
            _, source, target, raw_amount = tokens
            if raw_amount.isascii() and raw_amount.isdigit():
                amount = int(raw_amount)
                if (
                    amount > 0
                    and source != target
                    and source in balances
                    and target in balances
                    and source not in frozen
                    and balances[source] >= amount
                ):
                    balances[source] -= amount
                    balances[target] += amount
                    action = ("transfer", source, target, amount)
                    success = True

        elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
            _, account = tokens
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    action = ("freeze", account, False)
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    action = ("freeze", account, True)
                    success = True

        if success:
            if verb != "undo":
                history.append(action)
        else:
            rejected.append(i)

    return balances, rejected
